def ts(ms): s=ms//1000; return f"{s//60}:{s%60:02d}"
blocos=[]; falantes=[]
for n,ad in ADS.items():
    W=f'VSL-Pipeline-X0{n}'
    C=json.load(open(f'{W}/chunks.json')); assert len(C)==len(ad['pt']),(n,len(C),len(ad['pt']))
    falas=[{"falante":ad['falantes'][c['spk']],"ts":ts(c['start']),"en":c['en'],"pt":p} for c,p in zip(C,ad['pt'])]
    for f in falas:
        if f['falante'] not in falantes: falantes.append(f['falante'])
    prints=[]
    for s,sl,l in ad['prints']:
        arq=f"ad{n:02d}_{sl}_00-{s//60:02d}-{s%60:02d}.jpg"
        Image.open(f'{W}/full/{s:05d}.jpg').convert('RGB').save(f'VSL-Pipeline-ADS4/frames/{arq}','JPEG',quality=88)
        prints.append({"ts":ts(s*1000),"legenda":l,"arquivo":arq})
    b={"n":n,"titulo":ad['titulo'],"inicio":"0:00","fim":ts(C[-1]['end']),"falas":falas,"prints":prints}
    for k in ("rotulo_original","rotulo_pt"):
        if k in ad: b[k]=ad[k]
    blocos.append(b)
doc={"titulo":"ADS — pasta Drive (5 anúncios, lote 3) — Transcrição original + Tradução PT-BR + Prints",
 "fonte":"Fonte: pasta do Drive com 5 vídeos do TikTok (Download (27), Psychic Today, Sacerdotisa Dani Méllo, SumayaHypnotherapist Mentor e Theresa Lynn Reid). O Google Doc 'Cópia de Leva 06 - Prosperity' da mesma pasta não foi processado. Transcrição: AssemblyAI. O AD 03 é em português: no lugar da tradução vai o texto revisado, sem as repetições da fala. Tradução fiel nos demais: nomes, números e marcas mantidos como falados.",
 "nota_prints":"Minutagens: cada trecho traz o [m:ss] em que começa. Prints: frames dos momentos em que muda o gesto, o lettering ou aparece o produto, com legenda descrevendo a imagem e a fala do momento, nomeados adNN_descricao_HH-MM-SS.jpg na pasta frames/.",
 "falantes":falantes,"blocos":blocos}
json.dump(doc,open('VSL-Pipeline-ADS4/doc.json','w'),ensure_ascii=False,indent=1)
print(len(blocos),'ads',sum(len(b['falas']) for b in blocos),'trechos',sum(len(b['prints']) for b in blocos),'prints')
